def authorized(chunk, access):
    if chunk.tenant_id != access.tenant_id or chunk.doc_id not in access.allowed_doc_ids:
        return False
    if chunk.valid_from > access.as_of or (chunk.expires_at and access.as_of >= chunk.expires_at):
        return False
    if chunk.allowed_subjects or chunk.allowed_roles:
        return access.subject in chunk.allowed_subjects or bool(access.roles & chunk.allowed_roles)
    return True

def retrieve(query, chunks, access):
    candidates = [chunk for chunk in chunks if authorized(chunk, access)]
    return sorted(candidates, key=lambda chunk: chunk.chunk_id)
